const envelope = $json;
const supported = new Set(['ops.alert_raised','reconciliation.finding_raised','show.checklist_due','show.followup_due','blockchain.proof.confirmed','blockchain.proof.dead']);
if (!envelope || !supported.has(String(envelope.type)) || envelope.version !== 1) throw new Error('Unsupported CrowdRelay operations event');
const data = envelope.data ?? {};
const clean = (value, fallback = '-') => {
  const text = String(value ?? fallback).replace(/[\r\n\t]+/g, ' ').replace(/(?:token|secret|password|authorization|cookie)\s*[:=]\s*\S+/gi, '[REDACTED]').trim();
  return (text || fallback).slice(0, 300);
};
const titles = {
  'ops.alert_raised': 'ALERT SYSTEMOWY',
  'reconciliation.finding_raised': 'NIESPÓJNOŚĆ TICKETINGU',
  'show.checklist_due': 'CHECKLISTA KONCERTOWA',
  'show.followup_due': 'FOLLOW-UP PO KONCERCIE',
  'blockchain.proof.confirmed': 'PROOF ZAKOTWICZONY',
  'blockchain.proof.dead': 'PROOF ANCHOR DEAD',
};
const defaultSeverity = envelope.type === 'blockchain.proof.dead' ? 'critical' : (envelope.type.startsWith('show.') || envelope.type === 'blockchain.proof.confirmed' ? 'info' : 'warning');
const severity = clean(data.severity, defaultSeverity).toUpperCase();
const entity = clean(data.entity_label ?? data.event_title ?? data.entity_id ?? data.event_id ?? data.batch_id);
const kind = clean(data.kind ?? data.checklist ?? data.task ?? data.category ?? data.proof_kind);
const generatedSummary = envelope.type === 'blockchain.proof.confirmed'
  ? `Root ${clean(data.root_sha256).slice(0, 16)}… potwierdzony w chain ${clean(data.chain_id)} · block ${clean(data.block_number)}.`
  : envelope.type === 'blockchain.proof.dead'
    ? `Kotwiczenie nie powiodło się po ${clean(data.attempts)} próbach: ${clean(data.error_kind)}.`
    : null;
const summary = clean(data.summary ?? data.message ?? data.description ?? data.reason ?? generatedSummary);
const due = data.due_at ? clean(data.due_at) : null;
const marker = `CR_EVENT_ID:${envelope.id}`;
const content = [
  `## ${titles[envelope.type]}`,
  `**${severity}** · ${kind}`,
  entity !== '-' ? `Obiekt: ${entity}` : null,
  summary !== '-' ? summary : null,
  due ? `Termin: ${due}` : null,
  data.transaction_hash ? `Tx: ${clean(data.transaction_hash)}` : null,
  marker,
].filter(Boolean).join('\n\n').slice(0, 1950);
return [{ json: { marker, content, eventType: envelope.type } }];

const source = $('Validate and build operations alert').first().json;
const values = $input.all().map(item => item.json);
const messages = values.flatMap(value => Array.isArray(value) ? value : [value]);
const alreadySent = messages.some(message => typeof message?.content === 'string' && message.content.includes(source.marker));
return [{ json: { ...source, alreadySent } }];
